def solve(data):
    s = data['s']
    if not s:
        return ""

    result = []
    count = 1
    prev_char = s[0]

    for char in s[1:]:
        if char == prev_char:
            count += 1
        else:
            result.append(prev_char + str(count))
            count = 1
            prev_char = char

    # Append the last character and its count
    result.append(prev_char + str(count))

    return ''.join(result)

