def solve(data):
    m = data['m']
    n = len(m)
    if n == 0:
        return []

    # Create a new matrix to store the rotated version
    rotated_m = [[0] * n for _ in range(n)]

    # Rotate the matrix
    for i in range(n):
        for j in range(n):
            rotated_m[j][n - 1 - i] = m[i][j]

    return rotated_m

