from collections import Counter

def solve(data):
    if not data['nums']:
        return []

    counter = Counter(data['nums'])
    sorted_nums = sorted(counter.items(), key=lambda x: (-x[1], x[0]))

    result = []
    for num, count in sorted_nums:
        result.extend([num] * count)

    return result

def solve(data):
    if not data['words']:
        return ""

    # Start with the first word as the initial prefix
    prefix = data['words'][0]

    # Compare the prefix with each subsequent word
    for word in data['words'][1:]:
        while not word.startswith(prefix):
            # If the current word does not start with the prefix, remove the last character from the prefix
            prefix = prefix[:-1]
            # If the prefix becomes empty, there is no common prefix
            if not prefix:
                return ""

    return prefix

