def solve(data):
    base = data['base']
    n = data['n']

    if base < 2 or base > 36:
        raise ValueError("Base must be between 2 and 36")

    if n == 0:
        return '0'

    digits = []
    while n > 0:
        remainder = n % base
        if remainder >= 10:
            remainder = chr(remainder - 10 + ord('a'))
        else:
            remainder = str(remainder)
        digits.append(remainder)
        n //= base

    return ''.join(reversed(digits))

